files = set()
for dirpath, _, filenames in os.walk(root):
    if 'proto/gen' in dirpath:
        continue
    for fn in filenames:
        if not fn.endswith('.go'):
            continue
        path = os.path.join(dirpath, fn)
        try:
            text = open(path).read()
        except:
            continue
        if pattern.search(text):
            files.add(path)
        elif '/store/' in path and store_pattern.search(text):
            files.add(path)

for p in sorted(files):
    print(p.replace(root + '/', ''))
